/// <summary>
///  MPJ_21275_BackOrders
/// Extension of SalesLineBackOrder form datasource of SalesLine
/// </summary>
[ExtensionOf(formDataSourceStr(SalesLineBackOrder,SalesLine))]
final class METSalesLineBackOrder_SalesLine_Extension
{
    
}

Method.Source:
    /// <summary>
    ///  MPJ_21275_BackOrders
    ///  Based up on item id item name will display on the back order screen 
    /// </summary>
    public void init()
    {
        next init();

        Query       query       = new query(this.query());
        QueryRun    queryRun    = new QueryRun(query);

        while (queryRun.next())
        {
            SalesLine           salesLine           = queryRun.get(tableNum(SalesLine));
            SalesLine           salesLineBackOrder  = SalesLine::findRecId(salesLine.RecId, true);

            ttsbegin;
            if (salesLine.ItemId)
            {
                salesLineBackOrder.METItemName = salesLine.itemName();
                salesLineBackOrder.update();
            }
            ttscommit;
            salesLine.reread();
        }
    }
